import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const shurikenCard='a2-p08-r2c3',shurikenChants=['a2-p08-r1c2','a2-p10-r1c3','a2-p13-r1c1'] as const;
export const shurikenScenarios=['shuriken-ordinary','shuriken-guard','shuriken-owner-ordinary','shuriken-low','shuriken-dedicated','shuriken-subset','shuriken-all','shuriken-near','shuriken-fate','shuriken-maai','shuriken-evade','shuriken-keep','shuriken-mixed','shuriken-suppressed','shuriken-stopped','shuriken-silenced','shuriken-wrong-owner','shuriken-decline','shuriken-counter-ordinary','shuriken-counter-equal','shuriken-counter-dedicated'] as const;
export type ShurikenScenario=typeof shurikenScenarios[number];
export function isShurikenScenario(name:string):name is ShurikenScenario{return (shurikenScenarios as readonly string[]).includes(name);}
export function shurikenMode(name:ShurikenScenario){const dedicated=!['shuriken-ordinary','shuriken-guard','shuriken-owner-ordinary','shuriken-low','shuriken-counter-ordinary','shuriken-counter-equal','shuriken-decline'].includes(name),owner=dedicated&&name!=='shuriken-wrong-owner'||name==='shuriken-owner-ordinary',guard=!['shuriken-ordinary','shuriken-low','shuriken-counter-ordinary','shuriken-counter-equal','shuriken-decline'].includes(name),counter=name.includes('-counter-');return {dedicated,owner,guard,counter};}
export function makeShurikenPhysical(name:ShurikenScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number;incoming?:string}={}){
 const m=shurikenMode(name),prior=['shuriken-suppressed','shuriken-stopped','shuriken-silenced'].includes(name),incoming=options.incoming??(name==='shuriken-counter-equal'?'a2-p08-r1c3':'a2-p24-r1c2');let s=createGame(players,entropy(),{startingSeat:m.guard||m.counter?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'忍びのイダ':'侍大将のシン',m.owner?'侍大将のシン':'黒騎士ガーウィン','竜皇子アスフェルト','魔導王ガイナス'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?(options.spirit??6):6)-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.warrior_level!+=(options.warrior??(name==='shuriken-low'?3:m.dedicated?0:4))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,shurikenCard),takeCard(s,d,'a2-p02-r2c3')];if(m.guard)keep.push(takeCard(s,b,'a2-p22-r1c1'),takeCard(s,c,'a2-p19-r1c3'),takeCard(s,b,shurikenChants[0]),takeCard(s,b,shurikenChants[1]),takeCard(s,c,shurikenChants[2]));
 if(name==='shuriken-near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(name==='shuriken-maai')keep.push(takeCard(s,b,'a2-p06-r1c3'));if(name==='shuriken-evade')keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.counter)keep.push(takeCard(s,b,incoming));if(prior)keep.push(takeCard(s,d,name==='shuriken-suppressed'?'a2-p13-r1c2':name==='shuriken-stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 const haja=m.guard?takeCard(s,b,'a2-p01-r2c2'):null;if(haja){s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==haja);s.deck.push(haja);}for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`SHURIKEN_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SHURIKEN_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SHURIKEN_CARDS');}
 function settle(face=1){for(let n=0;n<500;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('SHURIKEN_LIMIT');}
 let cChanted=false;
 function advanceTo(target:string){for(let n=0;n<400;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w){act(w.participants[w.cursor]!,{type:'PASS'},prior?6:1);continue;}if(s.phase==='action'&&id===target)return;if(s.phase==='action'){if(m.guard&&id===c&&!cChanted){act(c,{type:'CHANT',cardInstanceId:shurikenChants[2],dedicated:false});cChanted=true;}else act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error(`SHURIKEN_PHASE_${s.phase}`);}throw Error('SHURIKEN_TURN_LIMIT');}
 for(const id of [a,b,c,d]){if(m.guard&&(id===b||id===c)){if(id===b)s.deck=[haja!,...s.deck.filter(x=>x!==haja)];act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:id===b?'a2-p22-r1c1':'a2-p19-r1c3'});}act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(m.guard){advanceTo(b);if(gameStats(s,b).chantLimit!==2)throw Error('SHURIKEN_HAJA_CAPACITY');act(b,{type:'CHANT',cardInstanceId:shurikenChants[0],dedicated:false});advanceTo(b);act(b,{type:'CHANT',cardInstanceId:shurikenChants[1],dedicated:false});}
 if(prior){advanceTo(d);act(d,{type:'ATTACK',cardInstanceId:name==='shuriken-suppressed'?'a2-p13-r1c2':name==='shuriken-stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();act(a,{type:'START_TURN'});settle(6);if(s.phase==='draw')act(a,{type:'CHOOSE_DRAW',draw:false});}else advanceTo(m.counter?b:a);
 if(m.counter){act(b,{type:'ATTACK',cardInstanceId:incoming,targetIds:[a],dedicated:false});for(let n=0;n<500&&s.windows?.at(-1)?.kind!=='normal-defense';n++){const w=s.windows!.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}else{if(name==='shuriken-subset'){act(d,{type:'REVEAL_CHARACTER'});settle();}if(name==='shuriken-near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}}return s;
}
